<?php
if(!defined('ABSPATH'))exit;
function pelham_update_locations(){
 if(!current_user_can('manage_options'))return new WP_Error('forbidden','Administrator access required.');
 foreach(json_decode(file_get_contents(__DIR__.'/../data/locations-confirmed.json'),true) as $slug=>$d){
  $posts=get_posts(['post_type'=>'pelham_terminal','name'=>$slug,'post_status'=>'any','numberposts'=>1]);
  if($posts){$p=$posts[0];$backup=['title'=>$p->post_title,'content'=>$p->post_content,'address'=>get_post_meta($p->ID,'pelham_address',true),'phone'=>get_post_meta($p->ID,'pelham_phone',true),'seo_title'=>get_post_meta($p->ID,'pelham_seo_title',true),'seo_description'=>get_post_meta($p->ID,'pelham_seo_description',true),'time'=>current_time('mysql')];if(!add_post_meta($p->ID,'pelham_before_locations_1_11',wp_slash($backup)))return new WP_Error('backup','Could not save location backup.');$id=wp_update_post(wp_slash(['ID'=>$p->ID,'post_title'=>$d['title'],'post_content'=>pelham_18_seed($d['content'])]),true);}
  else{$id=wp_insert_post(wp_slash(['post_type'=>'pelham_terminal','post_name'=>$slug,'post_title'=>$d['title'],'post_content'=>pelham_18_seed($d['content']),'post_status'=>'publish']),true);}
  if(is_wp_error($id))return $id;update_post_meta($id,'pelham_address',$d['address']);if($d['phone']!==null)update_post_meta($id,'pelham_phone',$d['phone']);update_post_meta($id,'pelham_seo_title',$d['seo']['seo_title']);update_post_meta($id,'pelham_seo_description',$d['seo']['description']);
 }
 $page=get_page_by_path('locations');if($page){foreach(json_decode(file_get_contents(__DIR__.'/../data/pages.json'),true) as $e)if($e['route']==='locations'){if(!add_post_meta($page->ID,'pelham_before_locations_1_11',wp_slash(['content'=>$page->post_content,'time'=>current_time('mysql')])))return new WP_Error('backup','Could not back up directory.');$r=wp_update_post(wp_slash(['ID'=>$page->ID,'post_content'=>pelham_18_seed($e['content'])]),true);if(is_wp_error($r))return $r;}}
 update_option('pelham_locations_release','1.11.0');return true;
}
add_action('admin_notices',function(){if(!current_user_can('manage_options')||get_current_screen()->id!=='toplevel_page_pelham-company'||get_option('pelham_locations_release')==='1.11.0')return;echo '<div class="notice notice-info"><h2>Confirmed Los Angeles, Miami and Orlando addresses</h2><p>Update the public location pages, directory and SEO metadata with the confirmed addresses. Miami phone: 323-201-4995. Preserve the existing Los Angeles phone; Orlando has no published phone. Backups are saved before replacement. Signed documents and applications are not changed.</p><form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="pelham_locations_111">';wp_nonce_field('pelham_locations_111');submit_button('Update confirmed locations (save backups)','secondary','submit',false);echo '</form></div>';});
add_action('admin_post_pelham_locations_111',function(){if(!current_user_can('manage_options'))wp_die('Forbidden',403);check_admin_referer('pelham_locations_111');if(get_option('pelham_locations_release')!=='1.11.0'){$r=pelham_update_locations();if(is_wp_error($r))wp_die(esc_html($r->get_error_message()));}wp_safe_redirect(admin_url('admin.php?page=pelham-company'));exit;});
